 "content": "def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) != 2:
        return out

    def nearby_count(pos):
        r, c = pos
        return sum(
            1
            for rr, row in enumerate(grid)
            for cc, value in enumerate(row)
            if value != 0 and value != 5 and (rr != r or cc != c)
        )

    # The marked location surrounded by the colored pattern is the source;
    # the isolated 5 is the destination.
    source = max(markers, key=nearby_count)
    target = markers[1] if source == markers[0] else markers[0]
    dr, dc = target[0] - source[0], target[1] - source[1]
    out[target[0]][target[1]] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                rr, cc = r + dr, c + dc
                if 0 <= rr < len(grid) and 0 <= cc < len(row):
                    out[rr][cc] = value
    return out
